use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::{DslValue,retained_clone::RetainedCloneSource,retirement::RetireOwned,source_fixture::{Wallet,receive}};
pub(crate) fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../🔗️sealed-shared-receiver/🧪️tests/🧫️fixtures/📐️.json")).unwrap()}
pub(crate) fn bank()->Wallet{Wallet::from_profile(&fixture()["stock"])}
pub(crate) fn source(value:DslValue,bank:&mut Wallet)->RetainedCloneSource<DslValue>{crate::source_fixture::capture(value,bank,|w|w.loan(1,4096),|w,p,work,h,g|w.post(p,work,g,h))}
pub(crate) fn post<E:std::fmt::Debug>(bank:&mut Wallet,turn:crate::RetainedWorkOutcome<RetainedCloneStep,E>,g:RetainedCloneGrant,h:(usize,usize),receipt:impl FnOnce(&E)->RetainedCloneProgress)->Result<RetainedCloneStep,E>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(receipt);assert!(turn.work<=1);bank.post(p,turn.work,g,h);turn.result}
pub(crate) fn original_turn<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,original:crate::retained_clone::RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,bank:&mut Wallet)->Result<RetainedCloneStep,crate::OriginalReceivingPrimary>{let(t,h)=crate::observe_retirement_allocations(||receive(control,g,bank.work_loan(1),|c|receiver.advance(original,c,4096,g)));post(bank,t,g,h,crate::OriginalReceivingPrimary::retained_progress)}
pub(crate) fn denied(g:RetainedCloneGrant,d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(yes,g)|yes.then_some(g))}
pub(crate) fn deny<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,original:crate::retained_clone::RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,bank:&mut Wallet,d:RetirementDemand){let g=bank.loan(1,4096);for g in denied(g,d){let(t,h)=crate::observe_retirement_allocations(||receive(control,g,bank.work_loan(1),|c|receiver.advance(original,c,4096,g)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(original,4096).unwrap(),d);}}
pub(crate) fn take<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,bank:&mut Wallet)->T{let d=receiver.take_demand().unwrap();let g=bank.loan(1,4096);for g in denied(g,d){let(t,h)=crate::observe_retirement_allocations(||receiver.take(g));assert_eq!(t.work,0);assert!(t.result.unwrap().is_none());assert_eq!(h,(0,0));}let(t,h)=crate::observe_retirement_allocations(||receiver.take(g));let p=t.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();bank.post(p,t.work,g,h);t.result.unwrap().unwrap().0}
pub(crate) fn close<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,bank:&mut Wallet){receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){return}let d=receiver.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096);let g=bank.loan(1,4096);for g in denied(g,d){let(t,h)=crate::observe_retirement_allocations(||receiver.close_step(g));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}let(t,h)=crate::observe_retirement_allocations(||receiver.close_step(g));post(bank,t,g,h,ValueError::retained_progress).unwrap();}panic!("shared receiver cancellation did not settle")}
pub(crate) fn drain<T:RetireOwned>(value:T,bank:&mut Wallet){let(mut owner,h)=crate::observe_retirement_allocations(||crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("shared fixture supports original closure")));assert_eq!(h,(0,0));for _ in 0..100000{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let g=bank.loan(1,4096);let(result,h)=crate::observe_retirement_allocations(||owner.step(g));let work=owner.last_turn_work();post(bank,crate::RetainedWorkOutcome{result,work},g,h,ValueError::retained_progress).unwrap();}panic!("shared source retirement did not settle")}
